141	const SIZES = [
142	  { value: 'xs', label: 'XS' },
143	  { value: 's', label: 'S' },
144	];
145	
146	/**
147	 * Module-scope (not describe-block-local) so both the "real recipe assertions" describe block
148	 * below AND the Fix 1 / Fix 2 (Scorer rework round 1) DOM-level proof blocks further down can
149	 * share one definition rather than each hand-duplicating the same literal selector strings.
150	 */
151	const STRETCH_KEY = `[data-card-slot="${CARD_SLOT.content}"] a::after`;
152	const CLOSE_LIFT_KEY = `[data-card-slot="${CARD_SLOT.close}"]`;
153	const CAROUSEL_LIFT_KEY = `[data-card-slot="${CARD_SLOT.carousel}"]`;
154	// Behavioural fix: the carousel arrow reveal (docblock point 6) — unlike every other reveal key
155	// below, these two are unconditional (no gating flag), so they're built straight off
156	// CAROUSEL_LIFT_KEY rather than a nested `[data-card-slot="content"] ...` path — the carousel
157	// wrapper is a direct child of Media's own root, a sibling of `content`, not nested under it.
158	const HOVER_CAROUSEL_KEY = `&:hover ${CAROUSEL_LIFT_KEY}`;
159	const FOCUS_WITHIN_CAROUSEL_KEY = `&:focus-within ${CAROUSEL_LIFT_KEY}`;
160	const CONTENT_LIFT_KEY = `[data-card-slot="${CARD_SLOT.content}"] button`;
161	const PRICE_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.price}"]`;
162	const SIZE_CHIPS_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.sizeChips}"]`;
163	const HOVER_PRICE_KEY = `&:hover ${PRICE_KEY}`;
164	const HOVER_SIZE_CHIPS_KEY = `&:hover ${SIZE_CHIPS_KEY}`;
165	// Fix 2 (Scorer rework round 1): the keyboard-reachable equivalent of each hover-reveal rule
166	// above — see this file's own docblock note on the compound-selector vs separate-key idiom
167	// question, resolved by reading zimmSearchInput.css.ts and globalStyles.ts's zimmFormRow/
168	// zimmFormRowInverse: both use a separate sibling key (`_focusWithin` alongside `_hover`), never
169	// a comma-joined compound selector. This file already uses raw selector strings (not Chakra's
170	// `_hover`/`_focusWithin` shorthand props) because the hover rules need a descendant-combinator
171	// path baked into the selector itself, so the equivalent here is a separate `'&:focus-within ...'`
172	// string key alongside the existing `'&:hover ...'` key, not a merged `'&:hover, &:focus-within ...'`
173	// selector.
174	const FOCUS_WITHIN_PRICE_KEY = `&:focus-within ${PRICE_KEY}`;
175	const FOCUS_WITHIN_SIZE_CHIPS_KEY = `&:focus-within ${SIZE_CHIPS_KEY}`;
176	// Fix C: notify-me's own reveal-key trio, all three living INSIDE the HOVER_CAPABLE_QUERY block
177	// (see zimmProductCard.css.ts docblock point 4 for why this is the opposite structure from price/
178	// size-chips above — the "hidden by default" half must not be reachable by a touch pointer).
179	const NOTIFY_ME_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.notifyMe}"]`;
180	const HOVER_NOTIFY_ME_KEY = `&:hover ${NOTIFY_ME_KEY}`;
181	const FOCUS_WITHIN_NOTIFY_ME_KEY = `&:focus-within ${NOTIFY_ME_KEY}`;
182	// Fix D: the PLP-only bag-icon mobile hide — a viewport-width gate, not a hover one (see
183	// zimmProductCard.css.ts docblock point 5). Built from the real `breakpoints` import (not a
184	// hand-typed literal) so this can't silently drift from what the source file actually emits —
185	// `breakpoints.md` is `'48em'`, not a `768px` string, despite that being its px-equivalent value.
186	const DESKTOP_QUERY = `@media (min-width: ${breakpoints.md})`;
187	const BAG_KEY = `[data-card-slot="${CARD_SLOT.content}"] [data-card-slot="${CARD_SLOT.bag}"]`;
188	
189	/** Mocks the scroll container's native `scrollTo` (absent under jsdom), same technique as
190	 *  zimmProductCardMedia/index.test.tsx's own mockScrollTo. */
191	const mockScrollTo = (): ReturnType<typeof vi.fn> => {
192	  const scrollContainer = screen.getByTestId('card-media-scroll');
193	  const scrollTo = vi.fn();
194	  scrollContainer.scrollTo = scrollTo;
195	  return scrollTo;
196	};
197	
198	/**
199	 * A complete, valid props object for a given variation — narrows on `variation` with a plain
200	 * `switch` (fine here: the "no switch/if on props.variation" constraint applies only to
201	 * index.tsx's own render body, not to test fixtures).
202	 *
203	 * Overloaded (not a single `(variation) => ZimmProductCardProps` signature) so a call site that
204	 * passes a literal (`buildCardProps('plp')`) gets back the properly *narrow* per-variation type,
205	 * not the full union — needed so a test can then add a variation-specific prop on top (e.g.
206	 * `{...buildCardProps('wishlist')} onRemove={fn}`) without TypeScript rejecting it as "not
207	 * present on every union member." A `test.each` call site passing a runtime (non-literal)
208	 * `variation` still resolves to the final, general overload below.
209	 */
210	function buildCardProps(variation: 'plp'): ZimmProductCardBaseProps & ZimmProductCardPlpVariation;
211	function buildCardProps(variation: 'home'): ZimmProductCardBaseProps & ZimmProductCardHomeVariation;
212	function buildCardProps(variation: 'wishlist'): ZimmProductCardBaseProps & ZimmProductCardWishlistVariation;
213	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps;
214	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps {
215	  const base = {
216	    id: 'p1',
217	    href: '/product/1',
218	    name: 'Natura Dress',
219	    headingLevel: 'h3' as const,
220	    primaryImage: PRIMARY,
221	  };
222	  switch (variation) {
223	    case 'wishlist':
224	      return { ...base, variation, colour: 'Ivory', size: 'M', onRemove: vi.fn() };
225	    case 'home':
226	      return { ...base, variation };
227	    case 'plp':
228	      return { ...base, variation };
229	    default:
230	      // Exhaustiveness guard — a new union member without a matching branch here fails `tsc`,
231	      // not silently falls through to a wrong variation's shape.
232	      return ((): never => {
233	        throw new Error(`buildCardProps: unhandled variation ${JSON.stringify(variation)}`);
234	      })();
235	  }
236	}
237	
238	describe('ZimmProductCardProps — discriminated union is enforced at compile time', () => {
239	  // Both cases below are type-only proof: `@ts-expect-error` makes `tsc --noEmit` fail this file
240	  // if the offending line does NOT produce a compile error (an "Unused '@ts-expect-error'
241	  // directive" diagnostic) — so these only stay green while the union genuinely rejects the
242	  // invalid shape. The runtime assertion is trivial; TypeScript strips the annotation either way,
243	  // so the object still constructs and runs at test time regardless of what `tsc` says about it.
244	  test('wishlist variation requires onRemove, colour and size (type-only)', () => {
245	    // @ts-expect-error — wishlist requires onRemove, colour and size; none are supplied here.
246	    const invalid: ZimmProductCardProps = {
247	      id: 'p1',
248	      href: '/product/1',
249	      name: 'Dress',
250	      headingLevel: 'h3',
251	      primaryImage: PRIMARY,
252	      variation: 'wishlist',
253	    };
254	    expect(invalid).toBeDefined();
255	  });
256	
257	  test('home variation does not accept onRemove (type-only)', () => {
258	    // Assigned to the narrow per-variation intersection, not the `ZimmProductCardProps` union
259	    // alias: TypeScript's excess-property check on a *union* target only flags a property as
260	    // excess when it is unknown to EVERY member, so `onRemove` (valid on the wishlist member)
261	    // would silently pass here even under `variation: 'home'` if assigned to the union type
262	    // directly — confirmed empirically while building this test (an earlier version of this
263	    // exact case, assigned to `ZimmProductCardProps`, produced an "unused @ts-expect-error"
264	    // compile error because of this). The narrow intersection has no such escape hatch: it is a
265	    // plain object type with no `onRemove` key anywhere, so the excess property is genuinely
266	    // unknown and TypeScript reports it.
267	    //
268	    // The directive sits directly above the `onRemove` line, not the `const invalid = {` line
269	    // above it: TS anchors this specific "object literal may only specify known properties"
270	    // diagnostic to the offending property's own line, and `@ts-expect-error` only suppresses
271	    // (and only counts as "used" for) a diagnostic reported on the *immediate next* line.
272	    const invalid: ZimmProductCardBaseProps & ZimmProductCardHomeVariation = {
273	      id: 'p2',
274	      href: '/product/1',
275	      name: 'Dress',
276	      headingLevel: 'h3',
277	      primaryImage: PRIMARY,
278	      variation: 'home',
279	      // @ts-expect-error — onRemove does not exist on the home variation's own shape.
280	      onRemove: () => {},
281	    };
282	    expect(invalid).toBeDefined();
283	  });
284	});
285	
286	describe('ZimmProductCard — AC1: primary image renders for every variation x availability', () => {
287	  const cases: Array<[ZimmProductCardProps['variation'], boolean]> = [
288	    ['plp', false],
289	    ['plp', true],
290	    ['home', false],
291	    ['home', true],
292	    ['wishlist', false],
293	    ['wishlist', true],
294	  ];
