296	  test.each(cases)('variation=%s, isUnavailable=%s renders the primary image', (variation, isUnavailable) => {
297	    wrap(<ZimmProductCard {...buildCardProps(variation)} isUnavailable={isUnavailable} />);
298	    const img = screen.getByRole('img', { name: PRIMARY.alt });
299	    expect(img).toHaveAttribute('src', PRIMARY.src);
300	  });
301	});
302	
303	describe('ZimmProductCard — exactly one real anchor regardless of variation', () => {
304	  test.each(['plp', 'home', 'wishlist'] as const)('variation=%s renders exactly one <a>', (variation) => {
305	    wrap(<ZimmProductCard {...buildCardProps(variation)} />);
306	    const links = screen.getAllByRole('link');
307	    expect(links).toHaveLength(1);
308	    expect(links[0]).toHaveAttribute('href', '/product/1');
309	  });
310	});
311	
312	/**
313	 * KNOWN LIMITATION — read before trusting these as proof of the real z-index layering.
314	 *
315	 * Every test below fires a click/keydown directly on the target control's own DOM node via
316	 * Testing Library. That proves the CALLBACK WIRING is correct: the right element calls the right
317	 * handler when it is actually interacted with. It does NOT prove that a real mouse click at that
318	 * screen position, in an actual browser, would land on that control rather than on the invisible
319	 * stretched-link `::after` overlay sitting over the whole card — jsdom performs no real layout,
320	 * paint, or hit-testing (no CSS cascade resolution, no stacking-context/z-index comparison, no
321	 * geometry at all); `fireEvent`/`user-event` dispatch straight to the node you name, bypassing
322	 * whatever a browser's hit-testing algorithm would actually resolve at that (x, y). The
323	 * `zimmProductCard.css.ts` recipe assertions further below prove the CSS this organism emits has
324	 * the right `position`/`z-index` values (verified by literally compiling it through this
325	 * project's real Stylis — see that describe block) — but going from "the right CSS values exist"
326	 * to "a real browser click lands on the right element" is exactly the gap a real-browser
327	 * (Playwright or manual) check is for. Treat this whole file as necessary, not sufficient, proof.
328	 */
329	describe('ZimmProductCard — every interactive control stays separately clickable (wiring only, see limitation above)', () => {
330	  test('the bag button fires onAddToBag independently of the name-link overlay (PLP)', async () => {
331	    const onAddToBag = vi.fn();
332	    const user = userEvent.setup();
333	    wrap(<ZimmProductCard {...buildCardProps('plp')} onAddToBag={onAddToBag} />);
334	    await user.click(screen.getByRole('button', { name: 'Add to bag' }));
335	    expect(onAddToBag).toHaveBeenCalledTimes(1);
336	  });
337	
338	  test('the carousel arrows fire independently of the name-link overlay when there is more than one image', async () => {
339	    const user = userEvent.setup();
340	    wrap(<ZimmProductCard {...buildCardProps('plp')} images={GALLERY} />);
341	    mockScrollTo();
342	    await user.click(screen.getByRole('button', { name: 'Next image' }));
343	    expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument();
344	  });
345	
346	  test('a size chip fires onSizeChipSelect independently of the name-link overlay (PLP)', async () => {
347	    const onSizeChipSelect = vi.fn();
348	    const user = userEvent.setup();
349	    wrap(<ZimmProductCard {...buildCardProps('plp')} sizeChipValues={SIZES} onSizeChipSelect={onSizeChipSelect} />);
350	    await user.click(screen.getByRole('radio', { name: 'S' }));
351	    expect(onSizeChipSelect).toHaveBeenCalledWith('s');
352	  });
353	
354	  test('the remove (close) button fires onRemove independently of the name-link overlay (Wishlist)', async () => {
355	    const onRemove = vi.fn();
356	    const user = userEvent.setup();
357	    wrap(<ZimmProductCard {...buildCardProps('wishlist')} onRemove={onRemove} />);
358	    const button = screen.getByRole('button', { name: 'Remove Natura Dress from wishlist' });
359	    await user.click(button);
360	    expect(onRemove).toHaveBeenCalledTimes(1);
361	  });
362	
363	  test('the bag button also fires onAddToBag on a Wishlist card, independently of the remove button', async () => {
364	    const onAddToBag = vi.fn();
365	    const user = userEvent.setup();
366	    wrap(<ZimmProductCard {...buildCardProps('wishlist')} onAddToBag={onAddToBag} />);
367	    await user.click(screen.getByRole('button', { name: 'Add to bag' }));
368	    expect(onAddToBag).toHaveBeenCalledTimes(1);
369	  });
