371	  test('the name link itself is still a real, working anchor to href, not swallowed by its own overlay', () => {
372	    wrap(<ZimmProductCard {...buildCardProps('plp')} />);
373	    expect(screen.getByRole('link', { name: 'Natura Dress' })).toHaveAttribute('href', '/product/1');
374	  });
375	});
376	
377	describe('ZimmProductCard — VARIATION_CONFIG drives composed-child props (a sample, not exhaustive — full matrix is Media/Content’s own test responsibility)', () => {
378	  test('home never renders the bag, attributes row or size chips', () => {
379	    wrap(<ZimmProductCard {...buildCardProps('home')} currentPrice="$100.00" />);
380	    expect(screen.queryByRole('button', { name: 'Add to bag' })).not.toBeInTheDocument();
381	    expect(document.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`)).not.toBeInTheDocument();
382	  });
