389	  test('plp out-of-stock renders a disabled bag and a notify-me CTA', () => {
390	    const onNotifyMe = vi.fn();
391	    wrap(<ZimmProductCard {...buildCardProps('plp')} isUnavailable onNotifyMe={onNotifyMe} />);
392	    expect(screen.getByRole('button', { name: 'Add to bag' })).toBeDisabled();
393	    // Fix C: the organism's own recipe hover-gates this button via `[data-card-slot="notifyMe"]`
394	    // (see zimmProductCard.css.ts docblock point 4) — needs the real attribute present on the
395	    // real composed tree, not just Content's own isolated test coverage of the same element.
396	    expect(screen.getByRole('button', { name: 'Notify me' })).toHaveAttribute('data-card-slot', 'notifyMe');
397	  });
398	
