/**
 * Real-recipe assertions — bypasses the useMultiStyleConfig mock entirely, same technique as
 * zimmProductCardMedia/index.test.tsx's "Fix 1" block and
 * zimmProductCardContent/index.test.tsx's own real-recipe block. The component-level tests above
 * all render through the flat mock at the top of this file, which cannot see whether the real
 * recipe ever regresses the hover-reveal media query, the stretched-link overlay, or the z-index
 * lift on the interactive controls.
 *
 * These string keys were independently verified by compiling this exact recipe shape through
 * this project's own installed Stylis (v4.2.0 — the same engine Emotion/Chakra invoke at
 * runtime): the plain descendant selectors below resolve exactly as written, scoped under this
 * recipe's own generated class, with no comma-list scoping surprises.
 */
describe('ZimmProductCard — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
  test('the stretched-link overlay is unconditional, absolutely positioned, and carries no z-index of its own', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const after = root[STRETCH_KEY] as Record<string, unknown>;
    expect(after.position).toBe('absolute');
    expect(after.inset).toBe(0);
    expect(Object.prototype.hasOwnProperty.call(after, 'zIndex')).toBe(false);
  });

  test('the content-button lift selector uses position:relative + zIndex:1 — that element is not positioned by its own component recipe', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const rule = root[CONTENT_LIFT_KEY] as Record<string, unknown>;
    expect(rule.position).toBe('relative');
    expect(rule.zIndex).toBe(1);
  });

  /**
   * Fix 3 (found during the manual real-browser check performed after the round-2 Scorer PASS):
   * this selector used to be `'[data-card-slot="carousel"] button'` with its own
   * `position: 'relative'` — see the docblock's point 2 for why that shape left the arrows
   * unclickable in a real browser despite this exact test previously passing for it. The fix
   * targets the `carousel` WRAPPER, not the buttons inside it, and (same as `close` below) sets
   * only zIndex — the wrapper is already `position: absolute` via ZimmProductCardMedia's own
   * recipe.
   */
  test('the carousel lift selector sets only zIndex, never position — the wrapper is already positioned by ZimmProductCardMedia’s own recipe', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const carouselLift = root[CAROUSEL_LIFT_KEY] as Record<string, unknown>;
    expect(carouselLift.zIndex).toBe(1);
    expect(Object.prototype.hasOwnProperty.call(carouselLift, 'position')).toBe(false);
  });

  /**
   * Behavioural fix, confirmed against the Jira AC ("when on desktop and the user hovers, then
   * the arrows appear") and live Figma (Carousel is `hidden="true"` on every Default-state
   * instance checked, visible only on the matching Hover-state instance, for both PLP and
   * Wishlist) — see docblock point 6. Unlike every other reveal in this file, this one is NOT
   * gated behind a `ZimmProductCardStyleProps` flag: `baseStyle({})` with no props at all must
   * still emit it, because desktop arrows behave identically across every variation whenever a
   * card has more than one image. `zimmProductCardMedia.css.ts`'s own `carousel` part used to
   * reveal itself unconditionally under its own `[HOVER_CAPABLE_QUERY]` block (a device-
   * CAPABILITY check, making arrows permanently visible on any hover-capable device) — that
   * sub-block is now removed entirely (see that file's own regression guard), so this pair is the
   * only reveal path left for the arrows.
   */
  test('carousel arrows: unconditional hover+focus-within reveal inside HOVER_CAPABLE_QUERY, present even with no other flags set', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    expect((hoverBlock[HOVER_CAROUSEL_KEY] as Record<string, unknown>).display).toBe('flex');
    expect((hoverBlock[FOCUS_WITHIN_CAROUSEL_KEY] as Record<string, unknown>).display).toBe('flex');
  });

  /**
   * Fix 1 (Scorer rework round 1): the close-button lift rule used to also set
   * `position: 'relative'`, which is what an earlier version of this exact test asserted for all
   * three lift keys together. That was proven wrong by rendering the real composed tree: Media's
   * own `close` recipe part already sets `position: 'absolute', top: 0, right: 0` on this exact
   * element, and this rule's `.css-root [data-card-slot="close"]` descendant+attribute selector
   * has higher specificity than Media's own single-class rule — so `position: 'relative'` here
   * WON the cascade and knocked the remove button out of its pinned top-right corner into normal
   * flow. The element is already positioned (by Media's own recipe), which is all `zIndex` needs
   * to take effect — a competing `position` value here was never necessary. See the DOM-level
   * proof below (real recipes composed through the real `chakra` factory + `getComputedStyle`)
   * for confirmation the fix actually restores the pinned position, not just that this key's shape
   * looks right in isolation.
   */
  test('the close lift selector sets only zIndex, never position — the element is already positioned by ZimmProductCardMedia’s own recipe', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    const closeLift = root[CLOSE_LIFT_KEY] as Record<string, unknown>;
    expect(closeLift.zIndex).toBe(1);
    expect(Object.prototype.hasOwnProperty.call(closeLift, 'position')).toBe(false);
  });

  test('root itself establishes the positioned ancestor the stretched-link overlay resolves against', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    expect((style.root as Record<string, unknown>).position).toBe('relative');
  });

  /**
   * Fix E (full-sweep follow-up audit): price's "hidden by default" half used to be an
   * unconditional root-level rule here — this test asserted exactly that shape before the fix.
   * Moved inside HOVER_CAPABLE_QUERY instead (mirroring notify-me's own Fix C shape), because an
   * unconditional hide left Home's price permanently invisible on a touch pointer (confirmed live:
   * the Home story showed no price at all at mobile widths) — Mobile has no Hover variant at all
   * to ever reveal it. `root[PRICE_KEY]` must now be undefined; the hide lives at
   * `hoverBlock[PRICE_KEY]` instead.
   */
  test('home (hoverRevealsPrice): price has NO unconditional rule (stays visible on touch), hides+reveals only inside HOVER_CAPABLE_QUERY, no size-selector rule at all', () => {
    const style = ZimmProductCardRecipe.baseStyle({ hoverRevealsPrice: true });
    const root = style.root as Record<string, unknown>;
    expect(root[PRICE_KEY]).toBeUndefined();
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    expect((hoverBlock[PRICE_KEY] as Record<string, unknown>).display).toBe('none');
    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).display).toBe('block');
    // Fix 2 (Scorer rework round 1): the focus-within equivalent must reveal identically, so a
    // keyboard-only user tabbing through the card sees the same state a mouse-hover would.
    expect((hoverBlock[FOCUS_WITHIN_PRICE_KEY] as Record<string, unknown>).display).toBe('block');
    expect(root[SIZE_CHIPS_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_WITHIN_SIZE_CHIPS_KEY]).toBeUndefined();
  });

  test('plp/wishlist (hoverHidesPrice + hoverRevealsSizeSelector): price visible by default, size-selector hidden by default, both swap on hover AND on focus-within', () => {
    const style = ZimmProductCardRecipe.baseStyle({ hoverHidesPrice: true, hoverRevealsSizeSelector: true });
    const root = style.root as Record<string, unknown>;
    // No unconditional price rule — Content's own natural rendering already shows it by default.
    expect(root[PRICE_KEY]).toBeUndefined();
    expect((root[SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('none');
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    expect((hoverBlock[HOVER_PRICE_KEY] as Record<string, unknown>).display).toBe('none');
    expect((hoverBlock[HOVER_SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('block');
    // Fix 2 (Scorer rework round 1): focus-within must swap identically to hover — a keyboard
    // user tabbing into the card (e.g. onto the bag button or a size chip) sees the size-selector
    // in place of the price, the same revealed state a mouse-hover produces, not a silently
    // unreachable one.
    expect((hoverBlock[FOCUS_WITHIN_PRICE_KEY] as Record<string, unknown>).display).toBe('none');
    expect((hoverBlock[FOCUS_WITHIN_SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('block');
  });

  test('with every hover flag false/absent, no hover-reveal or focus-within-reveal rule is emitted at all — a touch/no-hover pointer keeps the natural default permanently', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    expect(root[PRICE_KEY]).toBeUndefined();
    expect(root[SIZE_CHIPS_KEY]).toBeUndefined();
    const hoverBlock = (root[HOVER_CAPABLE_QUERY] ?? {}) as Record<string, unknown>;
    expect(hoverBlock[HOVER_PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_WITHIN_PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_WITHIN_SIZE_CHIPS_KEY]).toBeUndefined();
  });

  /**
   * Fix C (found during the SFCC-236 Step 6 visual audit): confirmed against the real Figma
   * Default+Hover Unavailable instances for every variation (desktop and mobile) that an
   * out-of-stock item must NOT get the price/size-selector swap, and that the size-chip wrapper
   * stays hidden PERMANENTLY (not just "not swapped in on hover") — index.tsx is responsible for
   * AND-ing `hoverHidesPrice`/`hoverRevealsSizeSelector` with `!isUnavailable`, and separately
   * computing `sizeSelectorUnavailable` to carry that permanent hide, before any of it reaches
   * this recipe. This test passes the exact shape a real `variation: 'plp', isUnavailable: true`
   * card would produce, alongside `hoverRevealsNotifyMe: true` (what `showNotifyMe` resolves to
   * for that same card once `onNotifyMe` is supplied).
   *
   * Fix F (full-sweep follow-up audit) revises this test's own price expectations: it used to
   * assert `root[PRICE_KEY]` was undefined ("price only ever shown via Content's own natural
   * rendering, never touched by this recipe at all"). That was true on Desktop but wrong on
   * Mobile — Figma's Mobile PLP/Wishlist Unavailable references hide price entirely (swapped for
   * notify-me), unlike Desktop's own additive treatment. `sizeSelectorUnavailable` now also
   * carries a mobile-hidden/desktop-shown price rule, asserted below.
   */
  test('unavailable PLP: no desktop price swap, size-chips permanently hidden, price hidden on mobile only, notify-me still hover-gates', () => {
    const style = ZimmProductCardRecipe.baseStyle({
      hoverHidesPrice: false,
      hoverRevealsPrice: false,
      hoverRevealsSizeSelector: false,
      hoverRevealsNotifyMe: true,
      sizeSelectorUnavailable: true,
    });
    const root = style.root as Record<string, unknown>;
    // Both price and size-chips get an unconditional (mobile-first) rule now — a permanent hide
    // for size-chips (no reveal anywhere), and a mobile-only hide for price (reveals again at
    // DESKTOP_QUERY, asserted further below).
    expect((root[PRICE_KEY] as Record<string, unknown>).display).toBe('none');
    expect((root[SIZE_CHIPS_KEY] as Record<string, unknown>).display).toBe('none');
    expect((root[DESKTOP_QUERY] as Record<string, unknown>)[PRICE_KEY]).toEqual({ display: 'block' });
    const hoverBlock = root[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
    expect(hoverBlock[PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_SIZE_CHIPS_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_WITHIN_PRICE_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_WITHIN_SIZE_CHIPS_KEY]).toBeUndefined();
    // Notify-me's "hidden by default" lives INSIDE the media query (docblock point 4) — never
    // emitted as an unconditional root-level rule, unlike price/size-chips' own unconditional half.
    expect(root[NOTIFY_ME_KEY]).toBeUndefined();
    expect((hoverBlock[NOTIFY_ME_KEY] as Record<string, unknown>).display).toBe('none');
    expect((hoverBlock[HOVER_NOTIFY_ME_KEY] as Record<string, unknown>).display).toBe('block');
    expect((hoverBlock[FOCUS_WITHIN_NOTIFY_ME_KEY] as Record<string, unknown>).display).toBe('block');
  });

  test('hoverRevealsNotifyMe absent/false emits no notify-me rule at all — matches an in-stock card, where notify-me never mounts', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    expect(root[NOTIFY_ME_KEY]).toBeUndefined();
    const hoverBlock = (root[HOVER_CAPABLE_QUERY] ?? {}) as Record<string, unknown>;
    expect(hoverBlock[NOTIFY_ME_KEY]).toBeUndefined();
    expect(hoverBlock[HOVER_NOTIFY_ME_KEY]).toBeUndefined();
    expect(hoverBlock[FOCUS_WITHIN_NOTIFY_ME_KEY]).toBeUndefined();
  });

  /**
   * Fix D (found during the SFCC-236 Step 6 visual audit): PLP's Mobile Card-content instance
   * has the bag icon hidden — confirmed via `get_metadata` on node 40002163:41479 (`Icons` frame
   * `hidden="true"`), unlike Desktop and unlike Wishlist's own Mobile instance (40002187:58472,
   * no `hidden` attribute at all). `DESKTOP_QUERY` is a viewport-width gate (`min-width`), a
   * genuinely different axis from `HOVER_CAPABLE_QUERY` above.
   */
  test('hideBagOnMobile: hidden by default, shown again (as flex, not block) from DESKTOP_QUERY up', () => {
    const style = ZimmProductCardRecipe.baseStyle({ hideBagOnMobile: true });
    const root = style.root as Record<string, unknown>;
    expect((root[BAG_KEY] as Record<string, unknown>).display).toBe('none');
    const desktopBlock = root[DESKTOP_QUERY] as Record<string, unknown>;
    // 'flex', not 'block' — ZimmProductCardContent's own bagWrapper part uses flex to centre the
    // icon; 'block' would silently flatten that centring rather than merely fail to apply, since
    // this selector's specificity beats Content's own single class either way.
    expect((desktopBlock[BAG_KEY] as Record<string, unknown>).display).toBe('flex');
  });

  test('hideBagOnMobile absent/false emits no bag-visibility rule at all — matches Home (never shows the bag) and Wishlist (shows it on every breakpoint)', () => {
    const style = ZimmProductCardRecipe.baseStyle({});
    const root = style.root as Record<string, unknown>;
    expect(root[BAG_KEY]).toBeUndefined();
    // [DESKTOP_QUERY] itself is always present (mirrors [HOVER_CAPABLE_QUERY]'s own unconditional
    // presence, asserted with the same `?? {}` fallback elsewhere in this file) — it's the BAG_KEY
    // entry inside it that must be absent when nothing needs a desktop reveal.
    const desktopBlock = (root[DESKTOP_QUERY] ?? {}) as Record<string, unknown>;
    expect(desktopBlock[BAG_KEY]).toBeUndefined();
  });

  /**
   * Regression test for a real bug this exact combination caused: `sizeSelectorUnavailable` and
   * `hideBagOnMobile` used to each spread their own separate `[DESKTOP_QUERY]` object into `root`
   * — a plain object spread doesn't deep-merge two spreads sharing a key, so whichever one came
   * last silently overwrote the other's `[DESKTOP_QUERY]` value entirely. Confirmed for real in a
   * live browser: an unavailable PLP card's price stayed `display: none` at desktop width even
   * though `window.matchMedia('(min-width: 48em)').matches` correctly reported `true` — every
   * existing jsdom test still passed at the time, because none of them set BOTH flags at once,
   * which is exactly the shape a real unavailable PLP card produces (PLP's own
   * `hideBagOnMobile: true` combined with `sizeSelectorUnavailable: true` once it's out of stock).
   * This test passes that exact realistic combination and checks BOTH rules survive together in
   * the one shared `[DESKTOP_QUERY]` block.
   */
  test('sizeSelectorUnavailable and hideBagOnMobile together (the real unavailable-PLP shape) both survive in the same shared [DESKTOP_QUERY] block', () => {
    const style = ZimmProductCardRecipe.baseStyle({ sizeSelectorUnavailable: true, hideBagOnMobile: true });
    const root = style.root as Record<string, unknown>;
    const desktopBlock = root[DESKTOP_QUERY] as Record<string, unknown>;
    expect((desktopBlock[PRICE_KEY] as Record<string, unknown>).display).toBe('block');
    expect((desktopBlock[BAG_KEY] as Record<string, unknown>).display).toBe('flex');
  });
});

/**
 * Fix C — DOM-level proof, same reasoning as Fix 1's own block below: an object-shape assertion
 * proves this recipe's `sizeSelectorUnavailable` key looks right in isolation, but not that a real
 * `[data-card-slot="sizeChips"]` element composed under the real generated root class actually
 * resolves to `display: none` once Emotion's cascade runs for real. Composes the real root recipe
 * (unavailable-PLP shape) with a bare marker div for the size-chips slot, through the real
 * (unmocked) `chakra` factory, and reads the jsdom-resolved value back via `getComputedStyle`.
 */
describe('ZimmProductCard — Fix C: size-chip wrapper is genuinely hidden when unavailable, not just un-revealed', () => {
  test('a real [data-card-slot="sizeChips"] element, composed under the real unavailable-PLP root recipe, resolves to display:none', () => {
    const rootStyle = ZimmProductCardRecipe.baseStyle({
      hoverHidesPrice: false,
      hoverRevealsPrice: false,
      hoverRevealsSizeSelector: false,
      sizeSelectorUnavailable: true,
    }).root;

    const { container } = render(
      <chakra.div __css={rootStyle}>
        <div data-card-slot="content">
          <div data-card-slot="sizeChips">size chips</div>
        </div>
      </chakra.div>,
    );

    const sizeChips = container.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`) as HTMLElement;
    expect(window.getComputedStyle(sizeChips).display).toBe('none');
  });
});

/**
 * Fix 1 (Scorer rework round 1) — DOM-level proof, not just an object-shape assertion. The
 * "real recipe assertions" block above proves this organism's OWN recipe object has the right
 * shape, but the actual bug was a CASCADE interaction between TWO separate recipes
 * (ZimmProductCardMedia's `close` part and this organism's `root` part) converging on the SAME
 * DOM node — that can only be proven by actually composing both recipes' real output through the
 * real Chakra/Emotion pipeline and reading the browser-resolved (here, jsdom-resolved) value back
 * via `getComputedStyle`, the same two real recipe modules the block above already imports
 * directly (bypassing the flat useMultiStyleConfig mock at the top of this file). `chakra` is
 * imported normally at the top of this file rather than via `vi.importActual` because the
 * `vi.mock('@chakra-ui/react', ...)` factory only overrides `useMultiStyleConfig` and spreads
 * `...actual` for everything else — `chakra` was never mocked, so it is already the real,
 * Emotion-backed factory and genuinely injects CSS into the jsdom document.
 *
 * This only asserts `position`/`top`/`right` — plain declarative property values, not real layout
 * geometry. Per this file's own "KNOWN LIMITATION" docblock (above the click-wiring describe
 * block) and `.claude/rules/testing.md`, jsdom performs no real layout/paint/hit-testing, so this
 * cannot prove a real mouse click lands on this button rather than some overlapping element —
 * only a real-browser/Playwright/manual check can prove that. It CAN correctly resolve which of
 * two competing same-property declarations wins a cascade by specificity, which is exactly what
 * this bug was and is what this test targets.
 */
describe('ZimmProductCard — Fix 1 (Scorer rework round 1): close button stays visually pinned', () => {
  test('the real close-button recipe, composed under the real organism root recipe in an actual rendered DOM node, resolves to position:absolute / top:0 / right:0 — not knocked into flow by the root’s lift rule', () => {
    const rootStyle = ZimmProductCardRecipe.baseStyle({
      hoverHidesPrice: true,
      hoverRevealsPrice: false,
      hoverRevealsSizeSelector: true,
    }).root;
    const closeStyle = ZimmProductCardMediaRecipe.baseStyle().close;

    // Reproduces the real app's exact shape: Media's own `close` part styles the button directly
    // (one generated class, applied via Media's own __css prop in its own file); this organism's
    // `root` recipe's `[data-card-slot="close"]` descendant+attribute selector is a SECOND,
    // higher-specificity rule reaching the same button from the organism's own generated class on
    // its ancestor `div`. Both are wired here via the real (unmocked) `chakra` factory, so the
    // actual Emotion CSS text these two recipes emit — and the actual cascade between them — is
    // what jsdom resolves, not a hand-simplified stand-in.
    const { container } = render(
      <chakra.div __css={rootStyle}>
        <chakra.button __css={closeStyle} data-card-slot="close">
          close
        </chakra.button>
      </chakra.div>,
    );

    const button = container.querySelector(`[data-card-slot="${CARD_SLOT.close}"]`) as HTMLElement;
    const computed = window.getComputedStyle(button);
    expect(computed.position).toBe('absolute');
    expect(computed.top).toBe('0px');
    expect(computed.right).toBe('0px');
  });
});

/**
 * Fix 3 (found during the manual real-browser check performed after the round-2 Scorer PASS) —
 * DOM-level proof, same technique and same caveat as the Fix 1 block above: this proves the
 * CASCADE resolves to the right declarative `position`/`zIndex` VALUES on the real composed node,
 * not that a real click lands there. That second half is exactly what jsdom cannot do (see this
 * file's own "KNOWN LIMITATION" docblock) and exactly what the manual real-browser check that
 * found this bug in the first place was for — a real `elementsFromPoint` probe at the arrow
 * button's own centre, confirmed the fix restores it as the topmost hit target once applied.
 */
describe('ZimmProductCard — Fix 3: carousel wrapper stays positioned and gains zIndex, not knocked static by the lift rule', () => {
  test('the real carousel-part recipe, composed under the real organism root recipe in an actual rendered DOM node, resolves to position:absolute (from Media) + zIndex:1 (from this organism)', () => {
    const rootStyle = ZimmProductCardRecipe.baseStyle({}).root;
    const carouselStyle = ZimmProductCardMediaRecipe.baseStyle().carousel;

    // Same real-composition technique as the Fix 1 block above: Media's own `carousel` part
    // styles the element directly (including its `transform: translateY(-50%)` — the actual root
    // cause of this bug, see the docblock), and this organism's `root` recipe's
    // `[data-card-slot="carousel"]` descendant+attribute selector is a second rule reaching the
    // same element from the organism's own generated class on its ancestor `div`.
    const { container } = render(
      <chakra.div __css={rootStyle}>
        <chakra.div __css={carouselStyle} data-card-slot="carousel">
          carousel
        </chakra.div>
      </chakra.div>,
    );

    const carousel = container.querySelector(`[data-card-slot="${CARD_SLOT.carousel}"]`) as HTMLElement;
    const computed = window.getComputedStyle(carousel);
    // Position comes from Media's own recipe, unclobbered — this organism's lift rule no longer
    // declares a competing `position` value here at all (see Fix 3 above).
    expect(computed.position).toBe('absolute');
    expect(computed.zIndex).toBe('1');
  });
});

/**
 * Fix 2 (Scorer rework round 1) — DOM-level proof that the `:focus-within` reveal genuinely
 * engages on a real focus event, not just that the recipe object carries the right string key
 * (already proven structurally in the "real recipe assertions" block above).
 *
 * IMPORTANT — this is `.matches()`-based, not `getComputedStyle()`-based, and that is a
 * deliberate, empirically-verified choice, not an oversight. This file's own "KNOWN LIMITATION"
 * docblock (above the click-wiring describe block) already establishes that jsdom performs no
 * real layout/paint/hit-testing; investigating this fix surfaced a SEPARATE, more specific jsdom
 * gap that docblock does not cover: `window.getComputedStyle()` in this project's installed jsdom
 * does not dynamically re-resolve a pseudo-class-gated rule after the DOM's focus state changes
 * post-mount, even for a bare self-referential `&:focus-within` rule with no descendant selector
 * at all (confirmed by direct experiment — a real `.focus()` call correctly updates
 * `document.activeElement` and correctly makes `element.matches(':focus-within')` return `true`,
 * but a subsequent `getComputedStyle()` read still reports the PRE-focus value). This is exactly
 * why Fix 1's proof above (a purely static cascade with no pseudo-class involved) could safely
 * use `getComputedStyle()` while this one cannot. `.matches()` against the exact literal
 * descendant-selector suffix the real recipe emits (`SIZE_CHIPS_KEY`, module-scope above) — with
 * only the Emotion-specific `&` swapped for a plain stand-in ancestor selector, since `&` is an
 * Emotion/PostCSS nesting token resolved at CSS-in-JS compile time, not a selector nwsapi
 * understands directly — correctly reflects the live DOM focus state both before and after a
 * real `.focus()` call, so it is what actually proves the mechanism here.
 */
describe('ZimmProductCard — Fix 2 (Scorer rework round 1): size chips reveal on keyboard focus, not just mouse hover', () => {
  test('an ancestor :focus-within + the real recipe’s own descendant-selector suffix flips from non-matching to matching once a nested control receives real focus', () => {
    const ANCESTOR_STAND_IN = '[data-testid="card-root"]';
    // Swap the Emotion-only `&` token for the stand-in ancestor selector above — the remaining,
    // actual descendant path comes straight from the real recipe's own module-scope constant,
    // not a hand-typed second copy.
    const revealSelector = FOCUS_WITHIN_SIZE_CHIPS_KEY.replace('&', ANCESTOR_STAND_IN);

    const { container } = render(
      <div data-testid="card-root">
        <div data-card-slot="content">
          <button type="button">Add to bag</button>
          <div data-card-slot="sizeChips">size chips</div>
        </div>
      </div>,
    );

    const sizeChips = container.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`) as HTMLElement;
    // Before focus lands anywhere in the card, the reveal selector does not match — mirrors the
    // unconditional (outside-media-query) `display: none` default a touch/no-hover pointer sees
    // permanently in the real recipe.
    expect(sizeChips.matches(revealSelector)).toBe(false);

    // A real `.focus()` call (not `fireEvent.focus`, which only dispatches a synthetic event
    // without moving `document.activeElement` — confirmed empirically not to engage
    // `:focus-within` matching here) on a descendant of the card root.
    screen.getByRole('button', { name: 'Add to bag' }).focus();

    // :focus-within on the card ROOT (not on the size-chip wrapper itself, which would be
    // circular — an element that is display:none is unfocusable and unreachable by Tab) bubbles
    // from this descendant's real focus state up to the root, so the reveal selector now matches
    // — the same live-DOM condition the real recipe's CSS rule keys its `display: block` off.
    expect(sizeChips.matches(revealSelector)).toBe(true);
  });

  test('the reveal selector still does not match a sibling control receiving focus outside the card root entirely', () => {
    const ANCESTOR_STAND_IN = '[data-testid="card-root"]';
    const revealSelector = FOCUS_WITHIN_SIZE_CHIPS_KEY.replace('&', ANCESTOR_STAND_IN);

    const { container } = render(
      <>
        <button type="button">Outside the card</button>
        <div data-testid="card-root">
          <div data-card-slot="content">
            <div data-card-slot="sizeChips">size chips</div>
          </div>
        </div>
      </>,
    );

    const sizeChips = container.querySelector(`[data-card-slot="${CARD_SLOT.sizeChips}"]`) as HTMLElement;
    screen.getByRole('button', { name: 'Outside the card' }).focus();

    // Guards against a selector so loose it would match regardless of where focus actually is —
    // focus outside the card root must never trigger the reveal.
    expect(sizeChips.matches(revealSelector)).toBe(false);
  });
});

/**
 * No `switch`/`if` on `props.variation` anywhere in this organism's render body (index.tsx) is
 * the extensibility AC's actual proof and is not practically assertable at runtime — a test could
 * only prove one execution path took/didn't take a branch, not that no such branch exists in the
 * source at all. Verified instead by direct inspection + a literal grep, reported alongside this
 * suite's results rather than encoded as a test:
 *
 *   grep -n "variation ===" index.tsx        -> no matches
 *   grep -n "switch (variation)" index.tsx   -> no matches
 *
 * Every layout/visibility decision in index.tsx instead reads from `VARIATION_CONFIG[variation]`
 * — a single object-property lookup, not a branching statement.
 */

