const { JSDOM } = require('/Users/marcel.a.n.navarro/Dev/zimmermann-pwa/node_modules/jsdom');

const dom = new JSDOM(
  `<!doctype html><html><body>
    <button id="a" type="button">A</button>
    <button id="b" type="button">B</button>
  </body></html>`,
  { pretendToBeVisual: true, url: 'http://localhost:3000' },
);

const { document } = dom.window;
const a = document.getElementById('a');
const b = document.getElementById('b');

function report(label) {
  console.log(
    label,
    '| activeElement:', document.activeElement.id || document.activeElement.tagName,
    '| a:focus-visible:', a.matches(':focus-visible'),
    '| b:focus-visible:', b.matches(':focus-visible'),
  );
}

report('initial');

// Simulate a REAL pointer-driven click+focus sequence on "a" (mousedown -> focus -> mouseup -> click),
// the same sequence @testing-library/user-event dispatches for user.click().
const MouseEvent = dom.window.MouseEvent;
a.dispatchEvent(new MouseEvent('pointerdown', { bubbles: true, cancelable: true }));
a.dispatchEvent(new MouseEvent('mousedown', { bubbles: true, cancelable: true }));
a.focus();
a.dispatchEvent(new MouseEvent('pointerup', { bubbles: true, cancelable: true }));
a.dispatchEvent(new MouseEvent('mouseup', { bubbles: true, cancelable: true }));
a.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));

report('after simulated pointer-click-focus on A');

// Now plain script .focus() on B, with NO pointer event at all this time.
b.focus();
report('after plain .focus() on B (no pointer event on B)');

// Does a keydown anywhere reset the heuristic?
document.dispatchEvent(new dom.window.KeyboardEvent('keydown', { key: 'Tab', bubbles: true }));
report('after a bare keydown Tab dispatched on document');

b.focus();
report('after re-focusing B following the keydown');

